Method.Source:
/// <summary>
/// PaffH 30.11.24
/// delete crosscompany all mappings
/// </summary>
public static void deleteAll()
{
    container conDataArea = conNull();
    conDataArea += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Fintech);
    conDataArea += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Kleinhuis);
    conDataArea += NDXHelperDataArea::DataAreaIdFromEnum(NDXDataAreaIdEnum::Niedax);
    int i;
    for (i = 1; i <= conLen(conDataArea); i++)
    {
        changecompany(conPeek(conDataArea, i))
        {
            NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
            delete_from nDXProdIdentPictureItemIdMapping;
            Info(strFmt("@NDXBase:NDXDeletedRecordsInDataArea", conPeek(conDataArea,i), nDXProdIdentPictureItemIdMapping.RowCount()));
        }
    }
}

/// <summary>
/// PaffH 27.12.24
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_itemPictureName">NDXBTItemPicture</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXProdIdentPictureItemIdMapping</returns>
public static NDXProdIdentPictureItemIdMapping find(ItemId _itemId, NDXBTItemPicture _itemPictureName, boolean _update = true)
{
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
    nDXProdIdentPictureItemIdMapping.selectForUpdate(_update);

    select firstonly nDXProdIdentPictureItemIdMapping
    where nDXProdIdentPictureItemIdMapping.ItemId == _itemId
        && nDXProdIdentPictureItemIdMapping.ItemPictureName == _itemPictureName;

    return nDXProdIdentPictureItemIdMapping;
}

/// <summary>
/// PaffH 02.01.25
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_update">boolean</param>
/// <param name = "_active">NoYes (Default: NoYes::Yes)</param>
/// <returns>NDXProdIdentPictureItemIdMapping</returns>
public static NDXProdIdentPictureItemIdMapping findActive(ItemId _itemId, boolean _update = true, NoYes _active = NoYes::Yes)
{
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
    nDXProdIdentPictureItemIdMapping.selectForUpdate(_update);

    select firstonly nDXProdIdentPictureItemIdMapping
    where nDXProdIdentPictureItemIdMapping.ItemId == _itemId
        && nDXProdIdentPictureItemIdMapping.Active == _active;

    return nDXProdIdentPictureItemIdMapping;
}

/// <summary>
/// PaffH 27.12.24
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_itemPictureName">NDXBTItemPicture</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXProdIdentPictureItemIdMapping</returns>
public static NDXProdIdentPictureItemIdMapping findOrCreate(ItemId _itemId, NDXBTItemPicture _itemPictureName, boolean _insert = true)
{
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping = NDXProdIdentPictureItemIdMapping::find(_itemid, _itemPictureName, true);
    if (!nDXProdIdentPictureItemIdMapping)
    {
        nDXProdIdentPictureItemIdMapping.ItemId = _itemId;
        nDXProdIdentPictureItemIdMapping.ItemPictureName = _itemPictureName;
        if (_insert)
        {
            nDXProdIdentPictureItemIdMapping.insert();
        }
    }
    return nDXProdIdentPictureItemIdMapping;
}

