/// <summary>
/// PaffH 02.01.25
/// </summary>
public void insert()
{
    try
    {
        super();
        this.updateNumberOfItemAssignments(this.ItemPictureName);
    }
    catch
    {
    }
}

/// <summary>
/// PaffH 04.01.25
/// </summary>
public void initValue()
{
    super();

    this.Active = NoYes::Yes;
}

/// <summary>
/// PaffH 04.01.25
/// </summary>
/// <param name = "_itemPictureName">NDXBTItemPicture</param>
private void updateNumberOfItemAssignments(NDXBTItemPicture _itemPictureName)
{
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
    select count(RecId) from nDXProdIdentPictureItemIdMapping
            where nDXProdIdentPictureItemIdMapping.ItemPictureName == _itemPictureName;
    NDXProdIdentPicture nDXProdIdentPicture = NDXProdIdentPicture::find(_itemPictureName, true);
    if (nDXProdIdentPicture && nDXProdIdentPicture.NumberOfItemAssignments != nDXProdIdentPictureItemIdMapping.RecId)
    {
        ttsbegin;
        nDXProdIdentPicture.NumberOfItemAssignments = nDXProdIdentPictureItemIdMapping.RecId;
        nDXProdIdentPicture.update();
        ttscommit;
    }
}
